import { ShadowConfig, TiledBoolProp } from "type";
import { GameScene } from "../GameScene";
import { calculateAngle, fastFloor, formatProperties } from "utils";

export class Shadow {
  constructor(scene: GameScene, config: ShadowConfig) {
    this.config = config;
    this.scene = scene;
    const props = formatProperties<"rectangle" | "static">(config.properties);

    const rectangle = props.rectangle as TiledBoolProp;
    const staticProp = props.static as TiledBoolProp;

    const sunShadow = this.createShadow();

    this.sprites = {
      sun: sunShadow,
      lights: [],
    };
  }
  private scene: GameScene;
  private config: ShadowConfig;

  private sprites: {
    sun: Phaser.GameObjects.Sprite;
    lights: Phaser.GameObjects.Sprite[];
  };

  private createShadow = () => {
    const { height, width, x, y, id } = this.config;

    const sprite = this.scene.add.sprite(
      x + width / 2,
      y + height,
      "shadow_texture",
    );
    sprite.setScale(width / sprite.width, height / sprite.height);
    sprite.setDepth(Infinity);
    sprite.setOrigin(0.5, 1);
    sprite.setAlpha(0.5);

    return sprite;
  };

  private rotateSunShadow = () => {
    const { sun, sceneConfig } = this.scene;
    const { sun: sunSprite } = this.sprites;
    const { height: configH, width: configW, x:configX, y:configY, } = this.config;

    const { x = 0, y = 0 } = sun?.sunPosition || {};
    const { x: sX, y: sY, width, height, scaleX, scaleY } = sunSprite;
    const angle = calculateAngle(x, y, sX, sY);
    sunSprite.setAngle(angle + 90);

    const percent = sceneConfig.currentTime % 1;
    const timeIndex = fastFloor(sceneConfig.currentTime);

    const yOrigin = configH / (configW)
    sunSprite.setOrigin(0, yOrigin);

    switch (timeIndex) {
      case 0:
        // sunSprite.setOrigin(0.5, 0.9);

        break;
      // case 1:
      //   break;
      // case 2:
      //   break;
      // case 3:
      //   break;

      default:
        // sunSprite.setOrigin(0.5, 1);
        break;
    }
  };

  update = () => {
    this.rotateSunShadow();
  };
}
